# Combobox Combobox ## Использование Использование Обязательным параметром является только  `items` . Внутри items может быть такой же вложенный массив items. Формат следующий: ```tsx
type Items = Array<{
    /**
     * Значение у item.
     */
    value: string;
    /**
     * Метка-подпись к item.
     */
    label: string;
    /**
     * Сторона открытия вложенного дропдауна относительно текущего элемента.
     * @default bottom-start
     */
    placement?: Placement;
    /**
     * Список дочерних items.
     */
    items?: Array<ItemOption>;
    /**
     * Item не активен.
     */
    disabled?: boolean;
    /**
     * Слот для контента слева.
     */
    contentLeft?: ReactNode;
    /**
     * Слот для контента справа.
     */
    contentRight?: ReactNode;
    /**
     * Classname для item.
     */
    className?: string;
    /**
     * Максимальная высота дочернего выпадающего списка.
     */
    listMaxHeight?: CSSProperties['height'];
}>;
```

Тип выбора задается свойством  `multiple` . В одиночном режиме  `value`  и  `defaultValue`  имеют тип  `string` , в множественном -  `string[]` . В одиночном режиме можно использовать  `mode="radio"` , если нужно запретить снятие выбора повторным кликом. В множественном режиме доступны  `selectAllOptions` ,  `isTargetAmount` ,  `targetAmount` ,  `renderValue`  и  `chipClickArea` . ## Appearance Appearance `appearance="viewMode"`  — режим просмотра. ```tsx
import React from 'react';
import { Combobox } from '@salutejs/sdds-finai';

export function App() {
    const items = [
        { value: 'option_1', label: 'Опция 1' },
        { value: 'option_2', label: 'Опция 2' },
    ];

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', maxWidth: '350px', height: '200px' }}>
            <Combobox items={items} appearance="default" label="Default" placeholder="Placeholder" />
            <Combobox items={items} appearance="viewMode" value="option_1" readOnly label="ViewMode" placeholder="Placeholder" />
        </div>
    );
}
```

## Примеры Примеры ```tsx
import React, { useState } from 'react';
import { Combobox } from '@salutejs/sdds-finai';

export function App() {
   const [value, setValue] = useState<string>('');

    const items = [
        {
            value: 'north_america',
            label: 'Северная Америка',
        },
        {
            value: 'south_america',
            label: 'Южная Америка',
            items: [
                {
                    value: 'brazil',
                    label: 'Бразилия',
                },
                {
                    value: 'argentina',
                    label: 'Аргентина',
                },
            ],
        },
    ];

    return (
        <div style={{ display: "flex", gap: "30px", height: "300px" }}>
            <div style={{ width: "300px" }}>
                <Combobox
                    items={items}
                    value={value}
                    onChange={setValue}
                    placeholder="Placeholder"
                    label="Label"
                    helperText="Helper text"
                />
            </div>
        </div>
    );
}
```

