В режиме множественного выбора placeholder можно скрыть, когда выбран хотя бы один чип. ```tsx
import React, { useState } from 'react';
import { Combobox } from '@salutejs/sdds-finai';

export function App() {
    const [value, setValue] = useState<string[]>(['north_america']);

    const items = [
        {
            value: 'north_america',
            label: 'Северная Америка',
        },
        {
            value: 'south_america',
            label: 'Южная Америка',
        },
    ];

    return (
        <div style={{ width: "300px", height: "300px" }}>
            <Combobox
                multiple
                items={items}
                value={value}
                onChange={setValue}
                placeholder={value.length > 0 ? '' : 'Placeholder'}
                label="Label"
                helperText="Helper text"
            />
        </div>
    );
}
```

Есть возможность задать значения по дефолту. Также можно управлять состоянием снаружи компонента. ```tsx
import React, { useState } from 'react';
import { Combobox, Button } from '@salutejs/sdds-finai';

export function App() {
    const [multipleValue, setMultipleValue] = useState<string[]>(['brazil', 'north_america']);

    const items = [
        {
            value: 'north_america',
            label: 'Северная Америка',
        },
        {
            value: 'south_america',
            label: 'Южная Америка',
            items: [
                {
                    value: 'brazil',
                    label: 'Бразилия',
                },
                {
                    value: 'argentina',
                    label: 'Аргентина',
                },
            ],
        },
    ];

    return (
        <div style={{ display: "flex", gap: "30px", height: "300px" }}>
            <div style={{ width: "300px" }}>
                <Combobox
                    multiple
                    items={items}
                    value={multipleValue}
                    onChange={setMultipleValue}
                    placeholder="Placeholder"
                    label="Label"
                    helperText="Helper text"
                />
            </div>

            <Button onClick={() => setMultipleValue([])}>Очистить</Button>
        </div>
    );
}
```

Иногда возникает необходимость вынесения выпадающего списка на уровни выше в DOM. К примеру, когда у родительского блока имеется скролл, и список будет обрезаться, чего хотелось бы избежать. Для такой реализации имеется пропс  `portal` , который принимает либо  `ref`  либо  `id`  html-тега. Также нужно прокинуть проп  `listWidth` , чтобы явно задать ширину списку. Если этого не сделать, то будет взята ширина 100% от блока, на который ведет ссылка портала. ```tsx
import React, { useRef, useState } from 'react';
import { Combobox } from '@salutejs/sdds-finai';

export function App() {
   const [value, setValue] = useState<string>('');

    const items = [
        {
            value: 'north_america',
            label: 'Северная Америка',
        },
        {
            value: 'south_america',
            label: 'Южная Америка',
            items: [
                {
                    value: 'brazil',
                    label: 'Бразилия',
                },
                {
                    value: 'argentina',
                    label: 'Аргентина',
                },
            ],
        },
    ];

    const ref = useRef(null);

    return (
        <div style={{ position: "relative", height: "300px" }} ref={ref}>
            <div style={{ width: "300px" }}>
                <Combobox
                    items={items}
                    value={value}
                    onChange={setValue}
                    placeholder="Placeholder"
                    label="Label"
                    helperText="Helper text"
                    portal={ref}
                    listWidth="300px"
                />
            </div>
        </div>
    );
}
```

`value`  и  `onChange`  - опциональные параметры. Если вы хотите  `uncontrolled`  вариант компонента - их пробрасывать необязательно. ```tsx
