```

Свойство alwaysOpened позволяет отображать Combobox всегда открытым. При этом closeAfterSelect игнорируется. ```tsx
 import React, { useState } from 'react';
 import { Combobox, Button } from '@salutejs/sdds-finai';

 export function App() {
     const [alwaysOpened, setAlwaysOpened] = useState(false);

     const items = [
         {
             value: 'north_america',
             label: 'Северная Америка',
         },
         {
             value: 'south_america',
             label: 'Южная Америка',
             items: [
                 {
                     value: 'brazil',
                     label: 'Бразилия',
                 },
                 {
                     value: 'argentina',
                     label: 'Аргентина',
                 },
             ],
         },
     ];

     return (
         <div style={{ height: "300px" }}>
             <div style={{width: "300px" }}>
                 <Button text={ alwaysOpened ? 'По умолчанию' : 'Всегда открыт' } onClick={() => setAlwaysOpened(!alwaysOpened)} style={{ marginBottom: '1rem' }} />
                 <Combobox
                     items={items}
                     placeholder="Placeholder"
                     label="Label"
                     helperText="Helper text"
                     alwaysOpened={alwaysOpened}
                 />
             </div>
         </div>
     );
 }
```

Свойство  `virtual`  позволяет виртуализировать выпадающий список. Для настройки высоты списка можно использовать свойство  `listMaxHeight` .
Работает только в одноуровневых списках. ```tsx
 import React from 'react';
 import { Combobox } from '@salutejs/sdds-finai';

 export function App() {
     const items = Array(5000).fill(1).map((_, i) => ({ value: i.toString(), label: i.toString() }));

     return (
         <div style={{ height: "300px" }}>
             <div style={{width: "300px" }}>
                 <Combobox
                     items={items}
                     virtual
                     listMaxHeight="200px"
                     placeholder="Placeholder"
                     label="Label"
                     helperText="Helper text"
                 />
             </div>
         </div>
     );
 }
```

Пример с бесконечной загрузкой элементов в списке. ```tsx
 import React, { useState } from 'react';
 import { Combobox } from '@salutejs/sdds-finai';

 export function App() {
     function getRandomData() {
         return Array(10)
             .fill(1)
             .map(() => {
                 const n = Math.floor(Math.random() * 90000000) + 10000000;
                 return { value: n.toString(), label: n.toString() };
             });
     };

     const [items, setItems] = useState(getRandomData());
     const [isInfiniteLoading, setIsInfiniteLoading] = useState(false);

     const getData = async () => {
         return new Promise((resolve) => {
             setTimeout(() => {
                 resolve(getRandomData());
             }, 1500);
         });
     };

     const handleScroll = async (e) => {
         if (isInfiniteLoading) return;

         if (e.currentTarget.scrollTop + e.currentTarget.offsetHeight + 10 > e.currentTarget.scrollHeight) {
             setIsInfiniteLoading(true);

             const res = await getData();

             setItems([...items, ...res]);

             setIsInfiniteLoading(false);
         }
     };

     return (
         <div style={{ height: "300px" }}>
             <div style={{ width: "300px" }}>
                 <Combobox
                     items={items}
                     listMaxHeight="200px"
                     placeholder="Placeholder"
                     label="Label"
                     helperText="Helper text"
                     onScroll={handleScroll}
                     afterList={isInfiniteLoading ? <center>Загружаю...</center> : undefined}
                 />
             </div>
         </div>
     );
 }
```

Работа с кнопкой "Выбрать всё" осуществляется через свойство  `selectAllOptions`  только в режиме  `multiple` : ```tsx
type SelectAllProps = {
    checked?: boolean;
    indeterminate?: boolean;
    label?: string;
    onClick?: () => void;
    sticky?: boolean;
};
```

Вся логика выбора элементов и взаимодействия с компонентом лежит на стороне пользователя. ```tsx
import React, { useState, useEffect } from 'react';
import { Combobox } from '@salutejs/sdds-finai';

export function App() {
    const flatItems = [
        {
            value: 'north_america',
            label: 'Северная Америка',
        },
        {
            value: 'rio_de_janeiro',
            label: 'Рио-де-Жанейро',
        },
        {
            value: 'sao_paulo',
            label: 'Сан-Паулу',
        },
        {
            value: 'buenos_aires',
            label: 'Буэнос-Айрес',
        },
        {
            value: 'cordoba',
            label: 'Кордова',
        },
        {
            value: 'bogota',
            label: 'Богота',
        },
        {
            value: 'medellin',
            label: 'Медельин',
        },
    ];

    const [value, setValue] = useState([]);
    const [checked, setChecked] = useState(false);
    const [indeterminate, setIndeterminate] = useState(false);

    const handleClick = () => {
        if (checked && !indeterminate) {
            setValue([]);
        } else {
            setValue(flatItems.map((item) => item.value));
        }
    };

    useEffect(() => {
        if (value.length === 0) {
            setChecked(false);
            setIndeterminate(false);
        } else if (value.length === flatItems.length) {
            setChecked(true);
            setIndeterminate(false);
        } else {
            setChecked(true);
            setIndeterminate(true);
        }
    }, [value]);

    return (
        <div style={{ display: "block", width: "300px", height: "300px" }}>
            <Combobox
                value={value}
                onChange={setValue}
                label="Label"
                placeholder="Placeholder"
                items={flatItems}
                multiple
                selectAllOptions={{
                    checked,
                    indeterminate,
                    onClick: handleClick,
                }}
                listMaxHeight="200px"
            />
        </div>
    );
}
```

Пример с добавлением нового элемента в список. ```tsx
import React, { useState } from 'react';
import { Combobox } from '@salutejs/sdds-finai';

export function App() {
    const shortListItems = [
        {
            value: 'north_america',
            label: 'Северная Америка',
        },
        {
            value: 'rio_de_janeiro',
            label: 'Рио-де-Жанейро',
        },
        {
            value: 'sao_paulo',
            label: 'Сан-Паулу',
        },
    ];

    const [items, setItems] = useState(shortListItems);
    const [value, setValue] = useState([]);
    const [textValue, setTextValue] = useState('');

    const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Enter') {
            setItems([...items, { value: textValue, label: textValue }]);
            setValue([...value, textValue]);
            setTextValue('');
        }
    };

    return (
        <div style={{ display: "block", width: "300px", height: "300px" }}>
            <Combobox
                multiple
                label="Label"
                placeholder="Placeholder"
                items={items}
                value={value}
                onChange={setValue}
                onChangeValue={setTextValue}
                onKeyDown={handleKeyDown}
                helperText="Введите новое слово"
                emptyStateDescription="Нажмите Enter, чтобы добавить значение в список."
            />
        </div>
    );
}
```

`renderSelectionIcon`  - свойство для кастомной настройки иконки выбора элемента. Принимает коллбэк с одним параметром:  `selected` . ```tsx
import React, { useState } from 'react';
import { Combobox } from '@salutejs/sdds-finai';

export function App() {
    const [value, setValue] = useState('brazil');

    const items = [
        {
            value: 'north_america',
            label: 'Северная Америка',
        },
        {
            value: 'south_america',
            label: 'Южная Америка',
            items: [
                {
                    value: 'brazil',
                    label: 'Бразилия',
                },
                {
                    value: 'argentina',
                    label: 'Аргентина',
                },
            ],
        },
    ];

    const renderSelectionIcon = (selected: boolean | 'indeterminate') => {
        if (selected === true) {
            return <div style={{ width: '10px', height: '10px', borderRadius: '100%', background: 'red' }} />;
        }

        if (selected === 'indeterminate') {
            return <div style={{ width: '10px', height: '10px', background: 'blue' }} />;
        }

        return null;
    };

    return (
        <div style={{ height: '300px' }}>
           <div style={{ width: '400px' }}>
                <Combobox
                    items={items}
                    value={value}
                    onChange={setValue}
                    renderSelectionIcon={renderSelectionIcon}
                />
            </div>
        </div>
    );
}
```

`beforeList`  и  `afterList`  добавляют контент в начало и конец списка. :::note
Слоты закреплены: скроллится только список,  `listMaxHeight`  ограничивает его, а не весь попап.
::: ```tsx
import React, { useState } from 'react';
import { BodyXS, Combobox, Divider, LinkButton, TabItem, Tabs } from '@salutejs/sdds-finai';

export function App() {
    const regions = [
        { value: 'all', label: 'Все' },
        { value: 'europe', label: 'Европа' },
        { value: 'asia', label: 'Азия' },
    ];

    const cities = [
        { value: 'berlin', label: 'Берлин', region: 'europe' },
        { value: 'paris', label: 'Париж', region: 'europe' },
        { value: 'rome', label: 'Рим', region: 'europe' },
        { value: 'madrid', label: 'Мадрид', region: 'europe' },
        { value: 'prague', label: 'Прага', region: 'europe' },
        { value: 'tokyo', label: 'Токио', region: 'asia' },
        { value: 'seoul', label: 'Сеул', region: 'asia' },
        { value: 'bangkok', label: 'Бангкок', region: 'asia' },
        { value: 'shanghai', label: 'Шанхай', region: 'asia' },
    ];

    const [region, setRegion] = useState('all');
    const [value, setValue] = useState([]);

    const items = cities.filter((item) => region === 'all' || item.region === region);

    return (
        <div style={{ display: "flex", gap: "30px", height: "420px" }}>
            <div style={{ width: "300px" }}>
                <Combobox
                    multiple
                    items={items}
                    value={value}
                    onChange={setValue}
                    label="Label"
                    placeholder="Placeholder"
                    listMaxHeight="200px"
                    beforeList={
                        <Tabs view="filled" size="xs" stretch>
                            {regions.map((item) => (
                                <TabItem
                                    key={item.value}
                                    view="secondary"
                                    size="xs"
                                    tabIndex={0}
                                    selected={item.value === region}
                                    onClick={() => setRegion(item.value)}
                                >
                                    {item.label}
                                </TabItem>
                            ))}
                        </Tabs>
                    }
                    afterList={
                        <>
                            <Divider />
                            <div
                                style={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'space-between',
                                    gap: '0.5rem',
                                    padding: '0.5rem 0.75rem',
                                }}
                            >
                                <BodyXS style={{ color: 'var(--text-secondary)' }}>
                                    {`В разделе: ${items.length}`}
                                </BodyXS>
                                <LinkButton
                                    size="xs"
                                    view="accent"
                                    text="Показать все"
                                    disabled={region === 'all'}
                                    onClick={() => setRegion('all')}
                                />
                            </div>
                        </>
                    }
                />
            </div>
        </div>
    );
}
```

## Взаимодействие с disabled-элементами Взаимодействие с disabled-элементами Изнутри компонента взаимодействие с disabled-элементами  невозможно . Ниже представлены примеры с  `selected`  и  `unselected`  disabled-элементом. ```tsx
    import React, { useState } from 'react';
    import { Combobox } from '@salutejs/sdds-finai';

    export function App() {
        const items = [
            {
                value: 'north_america',
                label: 'Северная Америка',
            },
            {
                value: 'south_america',
                label: 'Южная Америка',
                items: [
                    {
                        value: 'brazil',
                        label: 'Бразилия',
                        disabled: true,
                    },
                    {
                        value: 'argentina',
                        label: 'Аргентина',
                    },
                ],
            },
        ];

        const [value, setValue] = useState(['brazil']);

        return (
            <div style={{ display: "flex", height: "300px" }}>
                <div style={{ width: "300px" }}>
                    <Combobox
                        multiple
                        label="Label"
                        placeholder="Placeholder"
                        items={items}
                    />
                </div>

                <div style={{ width: "300px" }}>
                    <Combobox
                        multiple
                        label="Label"
                        placeholder="Placeholder"
                        items={items}
                        value={value}
                        onChange={setValue}
                        isTargetAmount
                    />
                </div>
            </div>
        );
    }
```

